data class CueStop(val argb: Long, val position: Float)

/** All lengths are dp, all durations are ms (playback speed 1× already applied). */
data class AiVisualCueSpec(
    val stops: List<CueStop> = listOf(
        CueStop(0xFF6449F5, 0f), // Iris
        CueStop(0xFF3A77FF, 0.4f), // Azure
        CueStop(0xFFC9EEFF, 1f), // Mist
    ),
    val linearGradient: Boolean = false,
    val gradientAngleDeg: Float = 90f,
    val highlightX: Float = 0f,
    val highlightY: Float = -0.3f,
    val highlightDrift: Float = 0.6f,
    val materialParams: List<Float> = listOf(0.8f, 0.7f, 0.4f, 0f), // 바깥 빛 번짐 · 감싸는 빛 세기 · 빛 회전 속도
    val glow: Float = 1.28f,
    val edgeSoftness: Float = 0.75f,
    val alpha: Float = 0.5f,                  // overall cue opacity
    val listAccent: Long = 0xFF6449F5,
    val listSurface: Long? = null,   // null = follow the system theme
    val shadowColor: Long = 0xFF2D216E,
    val listItems: List<Pair<String, String>> = listOf(
        "Move the meeting to 3:00 PM" to "Everyone can join · Room 3B is free",
        "Draft an agenda from notes" to "3 topics from the last review",
        "Send the prototype link" to "To all 5 attendees",
        "Summarize Mina’s comments" to "4 new since yesterday",
        "Block focus time" to "Tomorrow 10:00–12:00",
    ),
    // What the agent says at full screen (L3), above its list — its lines as the tool breaks them (*…* = strong) at messageSize, from messageTop,
    // messageInset in from the sides; its list follows listGap below it. It is written in letter by letter as the tool's Adaptive Screen writes:
    // from writeInMs after the cue starts spreading to full screen, a letter (or a space) every letterStaggerMs, each taking letterMs to come out
    // of a letterBlur dp blur, rising letterRise dp into place, inked within its first letterInk. Then its list, the same way, row by row:
    // listAfterSteps letters after the sentence's last, listStepSteps apart. L3 holds until all of it is written, and readMs longer (at least
    // l3HoldMs). As the cue goes it dissolves: blurred by half of messageBlur, drifting up messageDrift.
    val messageLines: List<String> = listOf(
        "Your *design meeting*",
        "is in 30 minutes.",
        "*Here’s what I can do.*",
    ),
    val messageSize: Float = 26f,
    val messageTop: Float = 50f,
    val messageInset: Float = 32f,
    val listGap: Float = 24f,
    val writeInMs: Float = 630f,
    val letterStaggerMs: Float = 16.5f,
    val letterMs: Float = 1725f,
    val letterInk: Float = 0.3f,
    val letterBlur: Float = 6f,
    val letterRise: Float = 3.3333f,
    val listAfterSteps: Int = 8,
    val listStepSteps: Int = 12,
    val readMs: Float = 1200f,
    val messageBlur: Float = 4.6667f,
    val messageDrift: Float = 3.3333f,
    val sphereDiameter: Float = 74f,
    val cardHeight: Float = 220f,
    val cardThickness: Float = 8f,
    val cardCorner: Float = 28f,
    val margin: Float = 16f,
    val topInset: Float = 40f,
    val bottomInset: Float = 88f,
    val cardTop: Float = -1f,              // < 0: card settles above bottomInset. >= 0: card slots in at this y (dp)
    val insertGap: Float = 16f,
    val shadowStrength: Float = 0.6f,
    val shadowBlur: Float = 18f,
    val shadowOffset: Float = 14f,
    // L1, the loading — the agent thinking: the sphere stretched sideways into a capsule (loadStretch ×), its lower part dissolving in a
    // progressive blur (loadBlur dp at its bottom). It fades in (from loadAppearMs, over loadFadeMs) and breathes: it narrows loadBreath of
    // the way to the circle and widens back, breathMs a breath (the demo loop: breathCount breaths from breathFromMs, then breathRestMs at
    // its full width). Its rim light keeps its full strength over the top rimFrom of its height and is gone by rimTo, × rimGain.
    val loadStretch: Float = 2f,
    val loadBlur: Float = 80f,
    val loadBreath: Float = 1f,
    val loadAppearMs: Float = 250f,
    val loadFadeMs: Float = 700f,
    val breathFromMs: Float = 300f,
    val breathCount: Int = 2,
    val breathMs: Float = 2700f,
    val breathRestMs: Float = 100f,
    val rimFrom: Float = 0.3f,
    val rimTo: Float = 1f,
    val rimGain: Float = 1.4f,
    val spreadMs: Float = 1500f,   // L1 → L2: the capsule spreads into the card, its blur clearing
    val transitionMs: Float = 800f,   // L2 → L3
    val fadeMs: Float = 600f,
    val l2HoldMs: Float = 2600f,
    val l3HoldMs: Float = 2600f,
    val vanishMs: Float = 2510f,   // the demo loop's last part: the cue fades out over fadeMs, then the screen settles
    // While the agent thinks, the content under the cue goes out of focus (the underlay's `thinking`, 0 → 1, within thinkInMs: blur it up to
    // 4.7 dp and fade it to 72%); it comes back into focus as the capsule spreads, from 0.1 × spreadMs to thinkOutTailMs after it
    val thinkInMs: Float = 1000f,
    val thinkOutTailMs: Float = 300f,
    val componentStaggerMs: Float = 60f,
    val phaseTransition: Boolean = false,
    val scrim: Boolean = true,
    val easing: CubicBezierEasing = CubicBezierEasing(0.6f, 0f, 0.1f, 1f),
)

enum class CueLevel { Idle, L1, L2, L3 }

// ───────────────────────────── Public composables ─────────────────────────────

/**
 * Plays the tool's loop forever: L1 loading (the capsule fades in and breathes twice) → it spreads into the card, which slots in + list
 * → L3 full-screen list → fade out.
 * [underlay] draws your screen under the cue. Push the content below the slot down by `insert`,
 * `fullscreen` (0..1) tells how far the cue has spread to full screen: blur and fade your content by it — the agent's message and
 * list take the screen (the tool: blurred 7 dp, faded to 10%).
 * `thinking` (0..1) tells how far your content should be out of focus while the agent thinks, e.g.
 * `Modifier.blur((max(thinking, 1.5f * fullscreen) * 4.7f).dp)` (Android 12+) and
 * `.alpha((1f - 0.28f * thinking) * (1f - 0.9f * fullscreen))`.
 */
@Composable
fun AiVisualCueDemoLoop(
    modifier: Modifier = Modifier.fillMaxSize(),
    spec: AiVisualCueSpec = AiVisualCueSpec(),
    background: Shader? = null,
    underlay: @Composable (insert: Dp, fullscreen: Float, thinking: Float) -> Unit = { _, _, _ -> },
) {
    val timeMs by rememberCueTimeMs()
    BoxWithConstraints(modifier) {
        val w = maxWidth.value
        val h = maxHeight.value
        val timeline = remember(spec, w, h) { CueTimeline(spec, w, h) }
        val frame = timeline.sample(timeMs)
        underlay((frame.push * (spec.cardHeight + spec.insertGap)).dp, (1f - frame.pose.fill) * frame.opacity, frame.thinking)
        CueLayer(spec, frame, timeMs, background)
    }
}

/**
 * Shows one level and animates whenever [level] changes. [CueLevel.Idle] fades the cue out.
 * L1 is the loading: the capsule breathes for as long as the agent thinks, and spreads (spreadMs) when the level moves on.
 */
@Composable
fun AiVisualCue(
    level: CueLevel,
    modifier: Modifier = Modifier.fillMaxSize(),
    spec: AiVisualCueSpec = AiVisualCueSpec(),
    background: Shader? = null,
    underlay: @Composable (insert: Dp, fullscreen: Float, thinking: Float) -> Unit = { _, _, _ -> },
) {
    val timeMs by rememberCueTimeMs()
    val now by rememberUpdatedState(timeMs)
    BoxWithConstraints(modifier) {
        val w = maxWidth.value
        val h = maxHeight.value
        val poses = remember(spec, w, h) { CuePoses(spec, w, h) }
        val initial = poses.forLevel(level) ?: poses.capsule
        var from by remember(poses) { mutableStateOf(initial) }
        var to by remember(poses) { mutableStateOf(initial) }
        var fromCap by remember(poses) { mutableFloatStateOf(if (initial === poses.capsule) 1f else 0f) }   // how much of the loading capsule the motion starts from
        var fromFull by remember(poses) { mutableStateOf(false) }                // the motion leaves full screen (what the agent says dissolves)
        var changedAt by remember { mutableFloatStateOf(0f) }                    // when the motion started
        var settledAt by remember { mutableFloatStateOf(0f) }
        val progress = remember { Animatable(1f) }
        val opacity = remember { Animatable(if (level == CueLevel.Idle) 0f else 1f) }
        val thinking = remember { Animatable(if (level == CueLevel.L1) 1f else 0f) }
        LaunchedEffect(level, poses) {
            val fade = tween<Float>(spec.fadeMs.toInt(), easing = FastOutSlowInEasing)
            val think = level == CueLevel.L1             // the content goes out of focus while the agent thinks, and comes back as the capsule spreads
            launch {
                val d = if (think) spec.thinkInMs else spec.spreadMs + spec.thinkOutTailMs
                thinking.animateTo(if (think) 1f else 0f, tween(d.toInt(), easing = CubicBezierEasing(0.65f, 0f, 0.35f, 1f)))
            }
            val target = poses.forLevel(level)
            if (target == null) {                       // Idle: fade out in place
                opacity.animateTo(0f, fade)
                return@LaunchedEffect
            }
            if (opacity.value < 0.01f) {                // invisible: jump to the new shape, then fade in
                from = target
                to = target
                fromCap = if (target === poses.capsule) 1f else 0f
                progress.snapTo(1f)
                settledAt = now
            }
            launch { opacity.animateTo(1f, if (target === poses.capsule) tween<Float>(spec.loadFadeMs.toInt(), easing = FastOutSlowInEasing) else fade) }
            if (target !== to) {
                fromCap = mixf(fromCap, if (to === poses.capsule) 1f else 0f, spec.easing.transform(progress.value))
                fromFull = to === poses.full
                changedAt = now
                from = interpPose(from, to, progress.value, spec.easing)
                to = target
                progress.snapTo(0f)
                val d = if (fromCap > 0.5f || target === poses.capsule) spec.spreadMs else spec.transitionMs
                progress.animateTo(1f, tween(d.toInt(), easing = LinearEasing))
                settledAt = now
            }
        }
        val tl = progress.value
        var pose = interpPose(from, to, tl, spec.easing)
        val cap = mixf(fromCap, if (to === poses.capsule) 1f else 0f, spec.easing.transform(tl))   // the capsule's share of the shape now: its blur, its rim
        val since = timeMs - settledAt
        var glowW = 28f * (1f + 0.15f * sin(2f * PI.toFloat() * timeMs / 2000f))
        if (to === poses.capsule && tl >= 1f) {        // L1: it breathes — narrows toward the circle and widens back
            val b = (0.5f - 0.5f * cos(2f * PI.toFloat() * since / spec.breathMs)) * spec.loadBreath
            pose = pose.copy(hx = mixf(pose.hx, pose.hy, b))
            glowW = 28f * (1f + 0.15f * b)
        }
        val comps = FloatArray(3)
        if (to !== poses.capsule) {
            for (i in 0 until 3) {
                comps[i] = when {
                    to === poses.full -> 1f
                    tl >= 1f -> clamp01((since - 120f - i * spec.componentStaggerMs) / 260f)
                    else -> 0f
                }
            }
        }
        val inTransition = spec.phaseTransition && tl < 1f
        val phase = if (inTransition) 2f * PI.toFloat() * spec.easing.transform(tl) else 0f
        val phaseAmt = if (inTransition) sin(PI.toFloat() * tl) else 0f
        val o = opacity.value
        val push = clamp01((1f - pose.elev) / 0.7f) * o
        // full screen: what the agent says and its list are written in as the cue spreads to it; they dissolve as it leaves or fades
        val sinceChange = timeMs - changedAt
        val leave = FastOutSlowInEasing.transform(clamp01(sinceChange / max(spec.fadeMs, 1f)))
        val sayMs: Float
        val sayGone: Float
        val cardOut: Float
        when {
            to === poses.full -> { sayMs = sinceChange; sayGone = 1f - o; cardOut = cardOutAt(spec, sinceChange) }
            fromFull && leave < 1f -> { sayMs = 1e7f; sayGone = leave; cardOut = 1f }
            else -> { sayMs = -1f; sayGone = 0f; cardOut = 0f }
        }
        val frame = CueFrame(pose, phase, phaseAmt, glowW, cueItems(spec, poses.card, comps, o, w, sayMs, cardOut, sayGone), o, push,
            spec.loadBlur * cap, mixf(2f, spec.rimFrom, cap), mixf(3f, spec.rimTo, cap), mixf(1f, spec.rimGain, cap), thinking.value,
            sayMs, sayGone)
        underlay((push * (spec.cardHeight + spec.insertGap)).dp, (1f - pose.fill) * o, thinking.value)
        CueLayer(spec, frame, timeMs, background)
    }
}

// ───────────────────────────── Motion (mirrors the tool's timeline) ─────────────────────────────

private data class CuePose(
    val cx: Float, val cy: Float, val hx: Float, val hy: Float, val r: Float,
    val elev: Float, val bevel: Float, val shadow: Float, val fill: Float, val scrim: Float,
)

/** One list row in dp. [sf] = 0 card style … 1 full-screen style; [blur] / [dy] (dp) while it is written in or dissolves. */
private class CueItem(val x: Float, val y: Float, val w: Float, val h: Float, val a: Float, val sf: Float, val blur: Float = 0f, val dy: Float = 0f)

private class CueFrame(
    val pose: CuePose, val phase: Float, val phaseAmt: Float, val glowW: Float,
    val items: List<CueItem>, val opacity: Float, val push: Float,
    val blur: Float = 0f,                                         // the loading capsule's progressive blur (dp at its bottom)
    val rimFrom: Float = 2f, val rimTo: Float = 3f, val rimGain: Float = 1f,   // the limits on its rim light (2, 3, 1: none)
    val thinking: Float = 0f,                                     // how far the content under the cue is out of focus
    val sayMs: Float = -1f,                                       // full screen: ms since the cue started spreading to it (< 0: not there)
    val sayGone: Float = 0f,                                      // … and how far what it shows has dissolved as the cue goes (0 … 1)
)

private fun mixf(a: Float, b: Float, t: Float) = a + (b - a) * t
private fun clamp01(x: Float) = x.coerceIn(0f, 1f)
private fun easeInOut3(t: Float) = if (t < 0.5f) 4f * t * t * t else 1f - (-2f * t + 2f).pow(3) / 2f
private fun easeOut3(t: Float) = 1f - (1f - t).pow(3)
private fun easeSine(t: Float) = -(cos(PI.toFloat() * t) - 1f) / 2f

/**
 * A letter — or a row of the list — at writing step [k], [ms] after the cue started spreading to full screen: alpha, blur (dp), lift (dp).
 * As the tool's Adaptive Screen writes: it is inked fast, then its blur clears and it rises into place slowly, so that a soft blurred tail
 * trails the writing point (a progressive blur).
 */
private fun letterAt(s: AiVisualCueSpec, k: Int, ms: Float): FloatArray {
    val wp = clamp01((ms - s.writeInMs - k * s.letterStaggerMs) / s.letterMs)
    val b = easeOut3(wp)
    return floatArrayOf(easeSine(clamp01(wp / s.letterInk)), (1f - b) * s.letterBlur, (1f - b) * s.letterRise)
}

/** What the agent says, in writing steps: every letter and every space (a line break stands for one). */
private fun messageSteps(s: AiVisualCueSpec): Int = s.messageLines.sumOf { it.replace("*", "").length } + max(s.messageLines.size - 1, 0)

/** The card's rows dissolving as the cue spreads to full screen ([ms] after it started): 0 … 1, as the tool's old sentence dissolves. */
private fun cardOutAt(s: AiVisualCueSpec, ms: Float): Float {
    val r0 = 0.1f * s.spreadMs
    val r1 = s.spreadMs + s.thinkOutTailMs
    return easeInOut3(clamp01((ms - r0) / (0.5f * (r1 - r0))))
}

/** The demo loop's L3: until the list's last row is written, and readMs longer — at least l3HoldMs (counted from the end of the spread). */
private fun fullHoldMs(s: AiVisualCueSpec): Float =
    max(s.l3HoldMs, s.writeInMs + (messageSteps(s) + s.listAfterSteps + 4 * s.listStepSteps) * s.letterStaggerMs + s.letterMs - s.transitionMs + s.readMs)

private fun interpPose(a: CuePose, b: CuePose, t: Float, ease: CubicBezierEasing): CuePose {
    val e = ease.transform(clamp01(t))
    val ex = ease.transform(clamp01(t * 1.15f))          // width leads
    val ey = ease.transform(clamp01((t - 0.12f) / 0.88f)) // height lags
    val es = ease.transform(clamp01((t - 0.15f) / 0.85f)) // shadow lags
    return CuePose(
        mixf(a.cx, b.cx, e), mixf(a.cy, b.cy, e), mixf(a.hx, b.hx, ex), mixf(a.hy, b.hy, ey), mixf(a.r, b.r, e),
        mixf(a.elev, b.elev, e), mixf(a.bevel, b.bevel, e), mixf(a.shadow, b.shadow, es), mixf(a.fill, b.fill, e), mixf(a.scrim, b.scrim, e),
    )
}

/**
 * The rows. Before full screen ([sayMs] < 0) the 3 rows inside the settled card. At full screen the card's rows dissolve as it spreads
 * ([cardOut]) and the 5-row list is written in after what the agent says, row by row as its letters are, [AiVisualCueSpec.listGap] below it;
 * as the cue goes they dissolve with it ([gone]).
 */
private fun cueItems(s: AiVisualCueSpec, card: CuePose, comps: FloatArray, opacity: Float, screenW: Float, sayMs: Float, cardOut: Float, gone: Float): List<CueItem> {
    val pad = 12f       // in the card: from its edges, rows 8 dp apart
    val gap = 8f
    val rowH = (card.hy * 2f - pad * 2f - gap * 2f) / 3f
    val rowW = card.hx * 2f - pad * 2f
    val fx = 16f       // full screen: SEED's global gutter, rows 72 dp tall, 12 dp apart, listGap under what the agent says
    val fH = 72f
    val fGap = 12f
    val fTop = s.messageTop + s.messageLines.size * s.messageSize * 1.34f + s.listGap
    val fW = screenW - fx * 2f
    val steps = messageSteps(s)
    return List(5) { i ->
        val cx = card.cx - card.hx + pad
        val cy = card.cy - card.hy + pad + i * (rowH + gap)
        if (sayMs < 0f) {
            if (i < 3) CueItem(cx, cy + (1f - comps[i]) * 10f, rowW, rowH, comps[i] * opacity, 0f) else CueItem(fx, 0f, fW, fH, 0f, 1f)
        } else {
            val w = letterAt(s, steps + s.listAfterSteps + i * s.listStepSteps, sayMs)
            if (i < 3 && cardOut < 1f && w[0] <= 0.001f) {
                CueItem(cx, cy, rowW, rowH, 1f - cardOut, 0f, 0.5f * s.messageBlur * cardOut, -s.messageDrift * cardOut)
            } else {
                CueItem(fx, fTop + i * (fH + fGap), fW, fH, w[0] * (1f - gone), 1f, w[1] + 0.5f * s.messageBlur * gone, w[2] - s.messageDrift * gone)
            }
        }
    }
}

private class CuePoses(s: AiVisualCueSpec, w: Float, h: Float) {
    // L1: the loading capsule — the sphere stretched sideways (loadStretch ×), no shadow; a breath narrows it toward the circle (hx → hy)
    val capsule = CuePose(w / 2f, s.topInset + 12f + s.sphereDiameter / 2f, s.sphereDiameter / 2f * s.loadStretch, s.sphereDiameter / 2f,
        s.sphereDiameter / 2f, 1f, s.sphereDiameter / 2f, 0f, 1f, 0f)
    val card = CuePose(w / 2f, if (s.cardTop >= 0f) s.cardTop + s.cardHeight / 2f else h - s.bottomInset - s.cardHeight / 2f,
        w / 2f - s.margin, s.cardHeight / 2f, s.cardCorner, 0.3f, s.cardThickness, 0.18f, 1f, 0f)
    val full = CuePose(w / 2f, h / 2f, w / 2f, h / 2f, 28f, 0.12f, 40f, 0f, 0f, 0.06f)
    val all = listOf(capsule, card, full)
    fun forLevel(l: CueLevel): CuePose? = when (l) {
        CueLevel.Idle -> null
        CueLevel.L1 -> capsule
        CueLevel.L2 -> card
        CueLevel.L3 -> full
    }
}

private class CueSegment(
    val hold: Boolean, val a: Int, val b: Int, val dur: Float,
    val loading: Boolean = false, val spread: Boolean = false, val comps: Boolean = false, val breathe: Boolean = false,
    val vanish: Boolean = false, val keep: Boolean = false,
) { var t0 = 0f }

private class CueTimeline(private val s: AiVisualCueSpec, private val w: Float, private val h: Float) {
    private val poses = CuePoses(s, w, h).all
    private val segs = listOf(
        CueSegment(true, 0, 0, s.breathFromMs + s.breathCount * s.breathMs + s.breathRestMs, loading = true),   // L1 loading: fade in, breathe
        CueSegment(false, 0, 1, s.spreadMs, spread = true),                       // it spreads into the card (L2), which slots in
        CueSegment(true, 1, 1, s.l2HoldMs, comps = true),                         // L2 list rows
        CueSegment(false, 1, 2, s.transitionMs, keep = true),                     // L3 spread to full screen
        CueSegment(true, 2, 2, fullHoldMs(s), breathe = true, keep = true),       // L3: what the agent says and its list, written in
        CueSegment(true, 2, 2, s.vanishMs, vanish = true, keep = true),           // fade out, then the screen settles
    )
    val loopMs: Float

    init {
        var t = 0f
        for (g in segs) { g.t0 = t; t += g.dur }
        loopMs = max(t, 1f)
    }

    fun sample(tMs: Float): CueFrame {
        val t = ((tMs % loopMs) + loopMs) % loopMs
        val g = segs.lastOrNull { it.t0 <= t } ?: segs.first()
        val local = t - g.t0
        val comps = FloatArray(3)
        var glowW = 28f
        var phase = 0f
        var phaseAmt = 0f
        var opacity = 1f
        var blur = 0f
        var rimFrom = 2f
        var rimTo = 3f
        var rimGain = 1f
        val pose: CuePose
        if (g.loading) {                                  // the agent thinks: the capsule fades in and breathes, back at its full width by the end
            val c = poses[0]
            val span = g.dur - s.breathFromMs - s.breathRestMs
            val x = if (span > 0f) s.breathCount * clamp01((local - s.breathFromMs) / span) else 0f
            val b = (0.5f - 0.5f * cos(2f * PI.toFloat() * x)) * s.loadBreath
            pose = c.copy(hx = mixf(c.hx, c.hy, b))
            val m = local - s.loadAppearMs
            opacity = if (m < 0f) 0f else FastOutSlowInEasing.transform(clamp01(m / s.loadFadeMs))
            glowW = 28f * (1f + 0.15f * b)
            blur = s.loadBlur
            rimFrom = s.rimFrom
            rimTo = s.rimTo
            rimGain = s.rimGain
        } else if (g.spread) {                            // … then spreads into the card: its blur clears, its rim light opens up
            val tl = clamp01(local / g.dur)
            val e = s.easing.transform(tl)
            pose = interpPose(poses[0], poses[1], tl, s.easing)
            blur = s.loadBlur * (1f - e)
            rimFrom = mixf(s.rimFrom, 2f, e)
            rimTo = mixf(s.rimTo, 3f, e)
            rimGain = mixf(s.rimGain, 1f, e)
            if (s.phaseTransition) {
                phase = 2f * PI.toFloat() * e
                phaseAmt = sin(PI.toFloat() * tl)
            }
        } else if (g.hold) {
            if (g.vanish) opacity = 1f - FastOutSlowInEasing.transform(clamp01(local / max(s.fadeMs, 1f)))
            if (g.comps) {
                for (i in 0 until 3) comps[i] = clamp01((local - 120f - i * s.componentStaggerMs) / 260f)
            }
            if (g.breathe || g.vanish) {
                glowW = 28f * (1f + 0.15f * sin(2f * PI.toFloat() * (local + if (g.vanish) s.l3HoldMs else 0f) / 2000f))
            }
            pose = poses[g.a]
        } else {
            val tl = clamp01(local / g.dur)
            pose = interpPose(poses[g.a], poses[g.b], tl, s.easing)
            if (s.phaseTransition) {
                phase = 2f * PI.toFloat() * s.easing.transform(tl)
                phaseAmt = sin(PI.toFloat() * tl)
            }
        }
        if (g.keep) comps.fill(1f)
        val push = clamp01((1f - pose.elev) / 0.7f) * opacity
        // full screen: its clock (ms since the cue started spreading to it), the card's rows dissolving, and all of it dissolving as the cue fades
        val full = segs[3]
        val vanish = segs[5]
        val sayMs = if (t >= full.t0) t - full.t0 else -1f
        val cardOut = if (sayMs >= 0f) cardOutAt(s, sayMs) else 0f
        val gone = if (t >= vanish.t0) FastOutSlowInEasing.transform(clamp01((t - vanish.t0) / max(s.fadeMs, 1f))) else 0f
        return CueFrame(pose, phase, phaseAmt, glowW, cueItems(s, poses[1], comps, opacity, w, sayMs, cardOut, gone), opacity, push,
            blur, rimFrom, rimTo, rimGain, thinking(t), sayMs, gone)
    }

    // how far the content under the cue is out of focus at t: it blurs from the start of the loading and comes back as the capsule spreads
    private fun thinking(t: Float): Float {
        val load = segs[0]
        val spread = segs[1]
        if (t < load.t0 + load.dur) return easeInOut3(clamp01((t - load.t0) / s.thinkInMs))
        val v = t - spread.t0
        val r0 = 0.1f * spread.dur
        val r1 = spread.dur + s.thinkOutTailMs
        return if (v in 0f..r1) 1f - easeInOut3(clamp01((v - r0) / (r1 - r0))) else 0f
    }
}

@Composable
private fun rememberCueTimeMs(): State<Float> = produceState(0f) {
    var start = -1L
    while (true) {
        withFrameNanos { now ->
            if (start < 0L) start = now
            value = (now - start) / 1_000_000f
        }
    }
}

// ───────────────────────────── Rendering ─────────────────────────────

@Composable
private fun CueLayer(spec: AiVisualCueSpec, frame: CueFrame, timeMs: Float, background: Shader?) {
    val dark = isSystemInDarkTheme()
    val accent = Color(spec.listAccent)
    val surface = spec.listSurface?.let { Color(it) }
    Box(Modifier.fillMaxSize()) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            ShaderCue(spec, frame, timeMs, background)
        } else {
            FallbackCue(spec, frame)
        }
        CueComponents(frame, accent, surface, dark, spec.listItems, spec.stops)
        CueMessage(frame, spec)
    }
}

/**
 * What the agent says at full screen (L3), above its list — the tool's 큐 적용 사례 sentence: regular, its key words strong (*…* in
 * [AiVisualCueSpec.messageLines]). It is written in letter by letter as the tool's Adaptive Screen writes — each letter out of a blur (the
 * blur shows on Android 12+), rising into place — and dissolves as the cue goes. Replace with your agent's own words (broken into lines).
 */
@Composable
private fun CueMessage(frame: CueFrame, spec: AiVisualCueSpec) {
    if (frame.sayMs < 0f || frame.sayGone >= 0.999f) return
    val lines = remember(spec.messageLines) { spec.messageLines.map { strongLetters(it) } }
    val regular = TextStyle(color = Color(0xFF5F5E5A), fontSize = spec.messageSize.sp)
    val strong = TextStyle(color = Color(0xFF232321), fontSize = spec.messageSize.sp, fontWeight = FontWeight.Bold)
    Column(Modifier.padding(start = spec.messageInset.dp, top = spec.messageTop.dp)) {
        var k = 0                                        // the writing step: every letter and every space
        lines.forEachIndexed { li, line ->
            if (li > 0) k++                              // (the space the line break stands for)
            Row(Modifier.height((spec.messageSize * 1.34f).dp), verticalAlignment = Alignment.CenterVertically) {
                line.forEach { (ch, bold) ->
                    val w = letterAt(spec, k++, frame.sayMs)
                    val a = w[0] * (1f - frame.sayGone)
                    val blur = w[1] + 0.5f * spec.messageBlur * frame.sayGone
                    BasicText(
                        ch.toString(),
                        Modifier
                            .offset(y = (w[2] - spec.messageDrift * frame.sayGone).dp)
                            .graphicsLayer { alpha = a }
                            .blur(blur.dp, BlurredEdgeTreatment.Unbounded),
                        style = if (bold) strong else regular,
                    )
                }
            }
        }
    }
}

/** A line of the message, "*strong* regular", as its letters, each with whether it is strong. */
private fun strongLetters(s: String): List<Pair<Char, Boolean>> {
    val out = ArrayList<Pair<Char, Boolean>>()
    var bold = false
    for (c in s) {
        if (c == '*') bold = !bold else out.add(c to bold)
    }
    return out
}

private class CueStops(stops: List<CueStop>) {
    private val sorted = stops.sortedBy { it.position }.ifEmpty { listOf(CueStop(0xFF3A77FF, 0f)) }
    val count = sorted.size.toFloat()
    val lab: List<FloatArray> = List(3) { i -> srgbToOklab(sorted[min(i, sorted.size - 1)].argb) }
    val pos: FloatArray

    init {
        val p0 = sorted[0].position
        val p1 = max(sorted.getOrElse(1) { sorted.last() }.position, p0 + 0.01f)
        val p2 = max(sorted.getOrElse(2) { sorted.last() }.position, p1 + 0.01f)
        pos = floatArrayOf(p0, p1, p2)
    }
}

@RequiresApi(Build.VERSION_CODES.TIRAMISU)
@Composable
private fun ShaderCue(spec: AiVisualCueSpec, frame: CueFrame, timeMs: Float, background: Shader?) {
    val shader = remember { RuntimeShader(CUE_AGSL) }
    val stops = remember(spec.stops) { CueStops(spec.stops) }
    Canvas(Modifier.fillMaxSize()) {
        val p = frame.pose
        val t = timeMs / 1000f
        val mp = spec.materialParams
        val angle = spec.gradientAngleDeg * PI.toFloat() / 180f
        shader.setFloatUniform("uRes", size.width, size.height)
        shader.setFloatUniform("uScale", density)
        shader.setFloatUniform("uCenter", p.cx, p.cy)
        shader.setFloatUniform("uHalf", p.hx, p.hy)
        shader.setFloatUniform("uRadius", p.r)
        shader.setFloatUniform("uElev", p.elev)
        shader.setFloatUniform("uBevel", p.bevel)
        shader.setFloatUniform("uShadow", p.shadow * spec.shadowStrength)
        shader.setFloatUniform("uShadowBlur", spec.shadowBlur * (0.4f + 0.6f * p.elev))
        shader.setFloatUniform("uShadowOff", spec.shadowOffset * p.elev)
        shader.setFloatUniform("uFill", p.fill)
        shader.setFloatUniform("uGlowW", frame.glowW)
        shader.setFloatUniform("uGlow", spec.glow)
        shader.setFloatUniform("uScrim", if (spec.scrim) p.scrim * frame.opacity else 0f)
        shader.setFloatUniform("uPhase", frame.phase)
        shader.setFloatUniform("uPhaseAmt", frame.phaseAmt)
        shader.setFloatUniform(
            "uHl",
            spec.highlightX + sin(t * 0.6f) * 0.10f * spec.highlightDrift,
            spec.highlightY + cos(t * 0.45f) * 0.07f * spec.highlightDrift,
        )
        shader.setFloatUniform("uTime", t)
        shader.setFloatUniform("uP", mp[0], mp[1], mp[2], mp[3])
        shader.setFloatUniform("uC0", stops.lab[0][0], stops.lab[0][1], stops.lab[0][2])
        shader.setFloatUniform("uC1", stops.lab[1][0], stops.lab[1][1], stops.lab[1][2])
        shader.setFloatUniform("uC2", stops.lab[2][0], stops.lab[2][1], stops.lab[2][2])
        shader.setFloatUniform("uPos", stops.pos[0], stops.pos[1], stops.pos[2])
        shader.setFloatUniform("uStopCount", stops.count)
        shader.setFloatUniform("uGradType", if (spec.linearGradient) 1f else 0f)
        shader.setFloatUniform("uDir", cos(angle), sin(angle))
        shader.setFloatUniform("uNeutral", 0.92f, 0.92f, 0.93f)
        shader.setFloatUniform("uEdgeSoft", spec.edgeSoftness)
        shader.setFloatUniform("uOpacity", frame.opacity * spec.alpha)
        shader.setFloatUniform("uBlurBottom", frame.blur)   // the loading capsule's progressive blur (its edge softens toward the bottom)
        shader.setFloatUniform("uBlurMix", 0f)
        shader.setFloatUniform("uBlurExt", 0f)
        shader.setFloatUniform("uRimFrom", frame.rimFrom)
        shader.setFloatUniform("uRimTo", frame.rimTo)
        shader.setFloatUniform("uRimGain", frame.rimGain)
        val sc = Color(spec.shadowColor)
        shader.setFloatUniform("uShadowCol", sc.red, sc.green, sc.blue)
        drawRect(brush = ShaderBrush(shader))
    }
}

/** API 26–32: same shapes, timing and colors, simplified material (and no progressive blur on the loading capsule). */
@Composable
private fun FallbackCue(spec: AiVisualCueSpec, frame: CueFrame) {
    val sorted = remember(spec.stops) { spec.stops.sortedBy { it.position } }
    Canvas(Modifier.fillMaxSize()) {
        val p = frame.pose
        val d = density
        if (spec.scrim) drawRect(Color.Black.copy(alpha = p.scrim * frame.opacity))
        val hx = max(p.hx, 0.5f)
        val hy = max(p.hy, 0.5f)
        val r = min(p.r, min(hx, hy)) * d
        val topLeft = Offset((p.cx - hx) * d, (p.cy - hy) * d)
        val sz = Size(hx * 2f * d, hy * 2f * d)
        val o = frame.opacity * spec.alpha
        val shadowA = 0.22f * p.shadow * spec.shadowStrength * o
        if (shadowA > 0.005f) {
            drawRoundRect(
                color = Color(spec.shadowColor).copy(alpha = shadowA),
                topLeft = topLeft + Offset(0f, spec.shadowOffset * p.elev * d),
                size = sz,
                cornerRadius = CornerRadius(r),
            )
        }
        val colorStops = if (sorted.size == 1) {
            arrayOf(0f to Color(sorted[0].argb), 1f to Color(sorted[0].argb))
        } else {
            sorted.map { it.position to Color(it.argb) }.toTypedArray()
        }
        val brush = Brush.radialGradient(
            *colorStops,
            center = Offset((p.cx + spec.highlightX * hx) * d, (p.cy + spec.highlightY * hy) * d),
            radius = max(hx, hy) * 1.35f * d,
        )
        if (p.fill > 0.01f) {
            drawRoundRect(brush = brush, topLeft = topLeft, size = sz, cornerRadius = CornerRadius(r), alpha = p.fill * o)
        }
        if (p.fill < 0.99f) {
            val sw = frame.glowW * d
            drawRoundRect(
                brush = brush,
                topLeft = topLeft + Offset(sw / 2f, sw / 2f),
                size = Size(max(sz.width - sw, 1f), max(sz.height - sw, 1f)),
                cornerRadius = CornerRadius(max(r - sw / 2f, 0f)),
                alpha = (1f - p.fill) * o,
                style = Stroke(width = sw),
            )
        }
    }
}

/** The rows' line icons (24 × 24 paths, stroked), one per row. */
private val CUE_ICON_PATHS = listOf(
    "M5 6.5h14a1.5 1.5 0 0 1 1.5 1.5v10.5a1.5 1.5 0 0 1-1.5 1.5H5a1.5 1.5 0 0 1-1.5-1.5V8A1.5 1.5 0 0 1 5 6.5zM3.5 10.5h17M8 4v4M16 4v4",   // calendar
    "M7 3.5h7l4.5 4.5V19a1.5 1.5 0 0 1-1.5 1.5H7A1.5 1.5 0 0 1 5.5 19V5A1.5 1.5 0 0 1 7 3.5zM14 3.5V8h4.5M8.5 12.5h7M8.5 16h5",   // doc
    "M10 14a4 4 0 0 0 5.66 0l3-3a4 4 0 0 0-5.66-5.66l-1.2 1.2M14 10a4 4 0 0 0-5.66 0l-3 3a4 4 0 0 0 5.66 5.66l1.2-1.2",   // link
    "M5 5h14a1.5 1.5 0 0 1 1.5 1.5v9A1.5 1.5 0 0 1 19 17h-8l-4.5 3.5V17H5a1.5 1.5 0 0 1-1.5-1.5v-9A1.5 1.5 0 0 1 5 5zM8 9.5h8M8 12.5h5",   // chat
    "M12 3.5a8.5 8.5 0 1 1 0 17a8.5 8.5 0 1 1 0-17zM12 7.5V12l3 2",   // clock
)

/** The cue's gradient at t (0–1), from its stops, mixed in sRGB. */
private fun stopColorAt(stops: List<CueStop>, t: Float): Color {
    val s = stops.sortedBy { it.position }
    if (s.isEmpty()) return Color.White
    if (t <= s[0].position) return Color(s[0].argb)
    for (i in 1 until s.size) {
        if (t <= s[i].position) {
            val a = Color(s[i - 1].argb)
            val b = Color(s[i].argb)
            val k = ((t - s[i - 1].position) / max(s[i].position - s[i - 1].position, 1e-6f)).coerceIn(0f, 1f)
            return Color(a.red + (b.red - a.red) * k, a.green + (b.green - a.green) * k, a.blue + (b.blue - a.blue) * k)
        }
    }
    return Color(s.last().argb)
}

/**
 * The list that appears where the cue settles (L2) and re-flows to full screen (L3), as SEED list items (SEED Design, Apache-2.0) on glass:
 * a 60% surface washed with the cue's own gradient (each row its part of it, top to bottom) and a thin white edge, r3 corners;
 * a 40 dp icon box tinted with the accent and its line icon, a regular title and a muted detail.
 * (The web tool also blurs what is behind each row by 16 dp; to do the same here, add a backdrop blur — e.g. a library
 * such as Haze on Android 12+.) Replace with your own content.
 */
@Composable
private fun CueComponents(frame: CueFrame, accent: Color, surface: Color?, dark: Boolean, texts: List<Pair<String, String>>, stops: List<CueStop>) {
    val base = surface ?: if (dark) Color(0xFF1E2028) else Color.White
    val lightSurface = base.luminance() > 0.5f
    val titleColor = if (lightSurface) Color(0xFF1A1C20) else Color(0xFFF3F4F5)    // SEED fg.neutral
    val detailColor = if (lightSurface) Color(0xFF555D6D) else Color(0xFFB0B3BA)   // SEED fg.neutral-muted
    val tint = accent.copy(alpha = 0.12f)
    val veil = base.copy(alpha = 0.6f)
    val edge = Color.White.copy(alpha = 0.55f)
    val shape = RoundedCornerShape(12.dp)
    val washT = listOf(0f, 0.2f, 0.4f, 0.6f, 0.8f)   // where each row's wash starts on the gradient (it runs on for 0.2)
    val washes = remember(stops) {
        washT.map { t -> Brush.horizontalGradient(listOf(stopColorAt(stops, t).copy(alpha = 0.2f), stopColorAt(stops, t + 0.2f).copy(alpha = 0.06f))) }
    }
    val icons = remember { CUE_ICON_PATHS.map { PathParser().parsePathString(it).toPath() } }
    frame.items.forEachIndexed { i, item ->
        if (item.a <= 0.001f || item.h < 8f) return@forEachIndexed
        val icon = min(mixf(32f, 40f, item.sf), item.h - 12f)
        val padL = mixf(12f, 16f, item.sf)
        val f1 = mixf(14f, 16f, item.sf)
        val f2 = mixf(12f, 13f, item.sf)
        val textX = padL + icon + 12f
        val textW = max(item.w - textX - padL, 4f)
        val (title, subtitle) = texts.getOrElse(i) { "" to "" }
        Box(
            Modifier
                .offset(item.x.dp, (item.y + item.dy).dp)
                .size(item.w.dp, item.h.dp)
                .graphicsLayer { alpha = item.a }
                .blur(item.blur.dp, BlurredEdgeTreatment.Unbounded)   // (while it is written in, or dissolves)
                .background(veil, shape)
                .background(washes[i % washes.size], shape)
                .border(1.dp, edge, shape),
        ) {
            Box(
                Modifier.offset(padL.dp, ((item.h - icon) / 2f).dp).size(icon.dp)
                    .background(tint, RoundedCornerShape(mixf(8f, 10f, item.sf).dp)),
                contentAlignment = Alignment.Center,
            ) {
                val path = icons.getOrNull(i)
                if (path != null) Canvas(Modifier.size((icon * 0.55f).dp)) {
                    val k = size.minDimension / 24f
                    scale(k, k, pivot = Offset.Zero) {
                        drawPath(path, accent, style = Stroke(width = 1.8f, cap = StrokeCap.Round, join = StrokeJoin.Round))
                    }
                }
            }
            Column(Modifier.offset(textX.dp, 0.dp).width(textW.dp).fillMaxHeight(), verticalArrangement = Arrangement.Center) {
                BasicText(title, maxLines = 1, overflow = TextOverflow.Ellipsis,
                    style = TextStyle(color = titleColor, fontSize = f1.sp))
                BasicText(subtitle, maxLines = 1, overflow = TextOverflow.Ellipsis,
                    style = TextStyle(color = detailColor, fontSize = f2.sp))
            }
        }
    }
}

private fun srgbToOklab(argb: Long): FloatArray {
    fun lin(c: Long): Float {
        val v = c / 255f
        return if (v <= 0.04045f) v / 12.92f else ((v + 0.055f) / 1.055f).pow(2.4f)
    }
    val r = lin((argb shr 16) and 0xFFL)
    val g = lin((argb shr 8) and 0xFFL)
    val b = lin(argb and 0xFFL)
    val l = (0.4122214708f * r + 0.5363325363f * g + 0.0514459929f * b).toDouble().pow(1.0 / 3.0).toFloat()
    val m = (0.2119034982f * r + 0.6806995451f * g + 0.1073969566f * b).toDouble().pow(1.0 / 3.0).toFloat()
    val s = (0.0883024619f * r + 0.2817188376f * g + 0.6299787005f * b).toDouble().pow(1.0 / 3.0).toFloat()
    return floatArrayOf(
        0.2104542553f * l + 0.7936177850f * m - 0.0040720468f * s,
        1.9779984951f * l - 2.4285922050f * m + 0.4505937099f * s,
        0.0259040371f * l + 0.7827717662f * m - 0.8086757660f * s,
    )
}

